deco.css:
.fd-bowl{position:fixed;bottom:0;left:2vw;width:92px;height:46px;border-radius:0 0 52% 52%/0 0 100% 100%;background:linear-gradient(180deg,rgba(166,58,30,.22),rgba(166,58,30,.05));box-shadow:0 -2px 0 rgba(166,58,30,.24);pointer-events:none}
.fd-steam{position:fixed;bottom:6vh;left:4vw;width:44px;height:7vh;background:radial-gradient(ellipse at 50% 100%,rgba(200,154,60,.24),rgba(200,154,60,0) 72%);animation:fd-rise 11s ease-in-out infinite;pointer-events:none}
.fd-bean{position:fixed;top:3vh;right:4vw;width:10px;height:10px;border-radius:50%;background:rgba(166,58,30,.38);pointer-events:none}
.fd-millet{position:fixed;left:0;bottom:1vh;width:8vw;height:4vh;background:radial-gradient(circle at 20% 60%,rgba(166,58,30,.16) 0 2px,rgba(166,58,30,0) 2px),radial-gradient(circle at 60% 30%,rgba(200,154,60,.20) 0 2px,rgba(200,154,60,0) 2px);pointer-events:none}
@keyframes fd-rise{0%,100%{transform:translateY(0);opacity:.6}50%{transform:translateY(-8px);opacity:1}}
@media (prefers-reduced-motion: reduce){.fd-steam{animation:none}}
